const now = new Date();
const start = new Date(now.getFullYear(), 0, 0);
const dayOfYear = Math.floor((now - start) / 86400000);
const cats = ['app', 'shopify-updates', 'shopify-tips'];
return [{ json: { category: cats[dayOfYear % 3], today: now.toISOString().slice(0, 10) } }];

const { category, today } = $input.first().json;
const topics = {
  app: 'Write about one specific Checkpoint: Store Scanner use case. Checkpoint is a Shopify app that scans stores for hidden issues. Choose one problem: leftover app scripts after uninstall, broken product images, missing descriptions, expired discounts still showing, duplicate meta tags, or empty metafields causing display bugs.',
  'shopify-updates': 'Write about one Shopify platform behavior or feature merchants should understand. Choose one: how app uninstalls leave code behind, Online Store 2.0 theme structure, Shopify Markets, metafields vs metaobjects, checkout extensibility, or how script tags work.',
  'shopify-tips': 'Write one practical how-to for Shopify merchants. Choose one: pre-launch QA checklist, safe theme updates, cleaning up after app uninstalls, maintaining store performance over time, SEO audit basics, managing discounts safely, or keeping the product catalog consistent.'
};
const sys = 'Write for a Shopify tools blog. Clear, direct, practical, no fluff. Audience: Shopify merchants and developers. Rules: title max 70 chars. Description: 1 sentence max 160 chars. Tags: 4-6 lowercase kebab-case strings. Slug: url-friendly from title. Content: 600-900 words Markdown with brief 2-3 sentence intro, then 5-7 sections with ## headings, lists where useful, final paragraph naturally mentions Checkpoint: Store Scanner with link https://apps.shopify.com/store-scanner-health-check. No emojis. No conclusion section. Output ONLY valid JSON with fields: title, description, tags, slug, content.';
return [{ json: { category, today, groqBody: { model: 'llama-3.3-70b-versatile', messages: [{ role: 'system', content: sys }, { role: 'user', content: topics[category] }], max_tokens: 2500, temperature: 0.7 } } }];

const { today } = $('Konu Kategorisi Belirle').first().json;
const raw = $input.first().json.choices[0].message.content.trim();
const jsonStr = raw.replace(/^```json?\n?/, '').replace(/\n?```$/, '').trim();
function sanitize(s) {
  return s.replace(/"(?:[^"\\]|\\.)*"/g, m => m.replace(/\n/g, '\\n').replace(/\r/g, '\\r').replace(/\t/g, '\\t'));
}
let post;
try { post = JSON.parse(sanitize(jsonStr)); } catch(e) { throw new Error('Groq parse error: ' + e.message + ' | Raw: ' + raw.slice(0, 300)); }
const fm = '---\ntitle: "' + post.title.replace(/"/g, '\\"') + '"\ndescription: "' + post.description.replace(/"/g, '\\"') + '"\npublishDate: "' + today + '"\ntags: [' + post.tags.map(t => '"' + t + '"').join(', ') + ']\ndraft: false\n---\n\n';
const markdown = fm + post.content;
const filePath = 'src/content/blog/' + post.slug + '.md';
const content = Buffer.from(markdown, 'utf8').toString('base64');
return [{ json: { filePath, content, title: post.title, slug: post.slug } }];
